"""Mandelbrot escape times computed on the GPU with wgpu, summarized on stdout."""

import contextlib
import os
import sys

import numpy as np

WORKGROUP = 8

SHADER = """
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    _pad: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> xs: array<f32>;
@group(0) @binding(2) var<storage, read> ys: array<f32>;
@group(0) @binding(3) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    let j = gid.y;
    if (i >= params.width || j >= params.height) {
        return;
    }
    let cx = xs[i];
    let cy = ys[j];
    var zx: f32 = 0.0;
    var zy: f32 = 0.0;
    var n: u32 = 0u;
    loop {
        if (n >= params.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let nx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = nx;
        n = n + 1u;
    }
    out[j * params.width + i] = n;
}
"""


def parse_input(path):
    with open(path) as f:
        lines = [line for line in f.read().splitlines() if line.strip()]
    if len(lines) < 2:
        raise ValueError("input must have two lines")
    first = lines[0].split()
    second = lines[1].split()
    if len(first) != 3 or len(second) != 4:
        raise ValueError("malformed input")
    width, height, limit = (int(t) for t in first)
    x_min, x_max, y_min, y_max = (float(t) for t in second)
    if not (1 <= width <= 1024 and 1 <= height <= 1024 and 1 <= limit <= 1000):
        raise ValueError("width/height/limit out of range")
    if not (x_min < x_max and y_min < y_max):
        raise ValueError("bounds must satisfy x_min < x_max and y_min < y_max")
    return width, height, limit, x_min, x_max, y_min, y_max


def grid_axes(width, height, x_min, x_max, y_min, y_max):
    """Point coordinates per column and per row, computed in double precision."""
    i = np.arange(width, dtype=np.float64)
    j = np.arange(height, dtype=np.float64)
    xs = x_min + (i + 0.5) * (x_max - x_min) / width
    ys = y_min + (j + 0.5) * (y_max - y_min) / height
    return xs.astype(np.float32), ys.astype(np.float32)


@contextlib.contextmanager
def stdout_to_stderr():
    """Keep anything the GPU stack prints off standard output."""
    sys.stdout.flush()
    saved = os.dup(1)
    try:
        os.dup2(2, 1)
        yield
    finally:
        sys.stdout.flush()
        os.dup2(saved, 1)
        os.close(saved)


def escape_times_gpu(width, height, limit, xs, ys):
    import wgpu

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    params = np.array([width, height, limit, 0], dtype=np.uint32)
    usage = wgpu.BufferUsage
    params_buf = device.create_buffer_with_data(data=params, usage=usage.UNIFORM)
    xs_buf = device.create_buffer_with_data(data=xs, usage=usage.STORAGE)
    ys_buf = device.create_buffer_with_data(data=ys, usage=usage.STORAGE)
    out_size = width * height * 4
    out_buf = device.create_buffer(size=out_size, usage=usage.STORAGE | usage.COPY_SRC)

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf, "offset": 0, "size": params_buf.size}},
            {"binding": 1, "resource": {"buffer": xs_buf, "offset": 0, "size": xs_buf.size}},
            {"binding": 2, "resource": {"buffer": ys_buf, "offset": 0, "size": ys_buf.size}},
            {"binding": 3, "resource": {"buffer": out_buf, "offset": 0, "size": out_size}},
        ],
    )

    encoder = device.create_command_encoder()
    compute_pass = encoder.begin_compute_pass()
    compute_pass.set_pipeline(pipeline)
    compute_pass.set_bind_group(0, bind_group)
    compute_pass.dispatch_workgroups(
        (width + WORKGROUP - 1) // WORKGROUP, (height + WORKGROUP - 1) // WORKGROUP, 1
    )
    compute_pass.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(out_buf)
    return np.frombuffer(data, dtype=np.uint32).reshape(height, width).copy()


def summarize(times, limit):
    times = times.astype(np.int64).ravel()
    inside = int(np.count_nonzero(times == limit))
    escaped = times[times < limit]
    bins = np.bincount((8 * escaped) // limit, minlength=8)[:8]
    mean = float(escaped.sum()) / escaped.size if escaped.size else 0.0
    lines = [f"INSIDE {inside}"]
    lines += [f"BIN {k} {int(bins[k])}" for k in range(8)]
    lines.append(f"MEAN {mean:.3f}")
    return lines


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    width, height, limit, x_min, x_max, y_min, y_max = parse_input(argv[1])
    xs, ys = grid_axes(width, height, x_min, x_max, y_min, y_max)
    with stdout_to_stderr():
        times = escape_times_gpu(width, height, limit, xs, ys)
    sys.stdout.write("\n".join(summarize(times, limit)) + "\n")
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

